#!/usr/bin/env python
#
# This script is invoked by the Makefile, to generate "derived" Makefile variables:
#
#   - PYTHON_INCDIR
#   - NUMPY_INCDIR
#   - PYBIND11_INCDIR
#   - PYEXT_SUFFIX
#   - KSGPU_DIR
#   - AUTOGENERATED_KERNELS
#
# Values of these variables are written to makefile_helper.out.


# These global boolean variables are used to control which kernels are procedurally generated.
# This is a tradeoff between coverage and compile time.
#
# In "production" builds, I set production_kernels=True, and debug_*_kernels=False.
# When developing, I usually set all flags to False, so that compile times are short.
# If I'm debugging something specific, then I'll set a debug flag.
# For a long CI-style test run, I'll set all flags to true (high compile time!)

production_kernels = True     # "production" CHIME/CHORD kernels
debug_dd_kernels = False      # debug dedispersion kernels
debug_pf_kernels = False      # debug peak-finding kernels
debug_pfo_kernels = False     # debug peak-finding output microkernel
debug_pfwr_kernels = False    # debug peak-finding weight reader kernels
debug_cdd2_kernels = False    # debug coalesced dedispersion-pf kernels
debug_gpu_dd = False          # end-to-end test of gpu dedisperser

####################################################################################################


import io
import os
import re
import sys
import sysconfig
import importlib.util

try:
    import pybind11
except:
    raise RuntimeError("Couldn't import pybind11 -- this is a fatal error")

try:
    import numpy
except:
    raise RuntimeError("Couldn't import numpy -- this is a fatal error")

# This way of getting KSGPU_DIR is awkward, but avoids importing 'ksgpu'.
# (This is useful since imports can generate unexpected output.)
ksgpu_spec = importlib.util.find_spec('ksgpu')
if ksgpu_spec is None:
    raise RuntimeError("Couldn't find 'ksgpu' package -- this is a fatal error")

# This way of importing 'pirate_frb.cuda generator' doesn't assume that the
# larger 'pirate_frb' package has been built or installed.
sys.path.insert(0, 'pirate_frb')
import cuda_generator


####################################################################################################


def main():
    s = io.StringIO()
    print("# Autogenerated by makefile_helper.py (which is automatically invoked by the Makefile)\n", file=s)

    python_incdir = sysconfig.get_config_var('INCLUDEPY')
    print("# Include directory for python headers", file=s)
    print("# From sysconfig.get_config_var('INCLUDEPY')", file=s)
    print(f"PYTHON_INCDIR = {python_incdir}\n", file=s)

    numpy_incdir = numpy.get_include()
    print("# Include directory for numpy headers", file=s)
    print("# From numpy.get_include()", file=s)
    print(f"NUMPY_INCDIR = {numpy_incdir}\n", file=s)

    pybind11_incdir = pybind11.get_include()
    print("# Include directory for pybind11 headers", file=s)
    print("# From pybind11.get_include()", file=s)
    print(f"PYBIND11_INCDIR = {pybind11_incdir}\n", file=s)

    pyext_suffix = sysconfig.get_config_var('EXT_SUFFIX')
    print("# Filename suffix for python extension modules", file=s)
    print("# From sysconfig.get_config_var('EXT_SUFFIX')", file=s)
    print("# Equivalent to 'python3-config --extension-suffix'", file=s)
    print(f"PYEXT_SUFFIX = {pyext_suffix}\n", file=s)

    ksgpu_dir = os.path.dirname(ksgpu_spec.origin)
    print("# Base directory for 'ksgpu' package", file=s)
    print("# From importlib.util.find_spec('ksgpu').origin", file=s)
    print(f"KSGPU_DIR = {ksgpu_dir}\n", file=s)

    print("# CUDA kernels that will be autogenerated (by running ./autogenerate_kernel.py)", file=s)
    print('AUTOGENERATED_KERNELS =', end='', file=s)
    for filename in autogenerated_kernel_filenames():
        print(f' \\\n    {filename}', end='', file=s)
    print(file=s)

    s = s.getvalue()
    outfile = 'makefile_helper.out'
    print(f'Writing {outfile}')

    with open(outfile,'w') as f:
        print(s, file=f, end='')

    # Show summary on stdout (for debugging).
    if False:
        for line in s.split('\n'):
            if (len(line) > 0) and (line[0] != '#'):
                print('   ', line)


####################################################################################################


def autogenerated_kernel_filenames():
    """
    Top-level generator for autogenerated kernels:

       - removes duplicate filenames ("lower-level" generators are allowed
         to emit duplicates freely)
     
       - converts basenames to 'src_lib/autogenerated_kernels/{basename}'
    """
    
    kernels = { }   # registry key -> basename

    # The generator autogenerated_kernel_basenames() is defined below.
    for basename in autogenerated_kernel_basenames():
        # The 'key' addresses a detail of our KernelRegistry: for some pf-kernels (namely
        # those beginning with 'pf_' but not 'pf_weight_reader' or 'pf_output', we don't
        # allow two kernels which are identical except for the same value of Dcore. In
        # these cases, we strip "DcoreNN" from the key, and then raise an exception if
        # two kernels have the same key but different basenames.
        key = basename
        if basename.startswith('pf_') and not basename.startswith(('pf_weight_reader', 'pf_output')):
            key = re.sub(r'_Dcore\d+', '', basename)

        prev = kernels.get(key)

        if prev is None:
            kernels[key] = basename
            yield f'src_lib/autogenerated_kernels/{basename}'
        elif prev != basename:
            raise RuntimeError("autogenerated_kernel_filenames: these two kernels are identical,"
                               f" except for the value of Dcore: {prev} {basename}")


def autogenerated_kernel_basenames():
    for kernel in autogenerated_dedispersion_kernels():
        yield kernel.kernel_basename
    
    for kernel in autogenerated_cdd2_kernels():
        for basename in kernel.all_kernel_basenames:
            yield basename

    for kernel in autogenerated_sbdd_kernels():
        yield kernel.kernel_basename

    for kernel in autogenerated_peak_finding_kernels():
        for basename in kernel.all_kernel_basenames:
            yield basename
    
    for kernel in autogenerated_pf_weight_reader_kernels():
        yield kernel.kernel_basename

    for kernel in autogenerated_pf_output_kernels():
        yield kernel.kernel_basename


def autogenerated_dedispersion_kernels():
    """
    Generates objects of type 'cuda_generator.MultiDedisperser'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """
    
    T, F = True, False

    # Triples are of the form (input_is_ringbuf, output_is_ringbuf, apply_input_residual_lags).
    # We always generate enough kernels to run 'pirate_frb -m test --dd', even if debug_dd_kernels == False.
    triples = [ (F,F,F), (F,T,F), (T,F,T) ]

    if debug_dd_kernels:
        triples += [ (F,F,T), (F,T,T), (T,F,F) ]

    for dtype in [ 'float', '__half' ]:
        for irb,orb,rlag in triples:
            nspec_list = [1,8] if debug_dd_kernels else [1]
            for nspec in nspec_list:
                yield cuda_generator.MultiDedisperser(
                    dtype = dtype,
                    apply_input_residual_lags = rlag,
                    input_is_ringbuf = irb,
                    output_is_ringbuf = orb,
                    nspec = nspec
                )

        
def autogenerated_peak_finding_kernels():
    """
    Generates objects of type 'cuda_generator.PeakFinder'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    # The parameter space (dtype, subband_counts, Wmax, Dcore, Dout, Tinner) is too
    # large to enumerate, so we chooise a few representative kernels.

    # "Corners" of parameter space (16 kernels total)
    # Subband counts here are randomly generated.

    if not debug_pf_kernels:
        return
    
    kernels = [
        ('fp32', (1,1), 1, 1, 1, 1),
        ('fp32', (5,5,2,1), 1, 1, 1, 32),
        ('fp32', (0,8,2,2,1), 1, 1, 32, 1),
        ('fp32', (7,0,3,1,1), 1, 32, 32, 1),
        ('fp32', (0,2,0,1), 16, 1, 1, 1),
        ('fp32', (1,1), 16, 1, 1, 32),
        ('fp32', (0,1), 16, 1, 32, 1),
        ('fp32', (2,11,1,0,1), 32, 32, 32, 1),
        ('fp16', (1,1), 1, 2, 2, 1),
        ('fp16', (3,6,5,2,1), 1, 2, 2, 32),
        ('fp16', (2,3,1,1), 1, 2, 32, 1),
        ('fp16', (0,3,2,1), 1, 32, 32, 1),
        ('fp16', (3,2,1), 32, 2, 2, 1),
        ('fp16', (2,1), 32, 2, 2, 32),
        ('fp16', (1,1,1), 32, 2, 32, 1),
        ('fp16', (3,4,2,1), 32, 32, 32, 1),
    ]

    # Add some randomly generated kernels.
    # python -m pirate_frb dev random_kernels --pf

    kernels += [
        ('fp32', (3, 1, 0, 1), 4, 1, 2, 1),
        ('fp16', (9, 0, 2, 2, 1), 2, 2, 2, 8),
        ('fp16', (1, 5, 2, 0, 1), 8, 4, 8, 4),
        ('fp32', (6, 3, 2, 1), 1, 2, 8, 4),
        ('fp32', (1, 4, 1, 1), 16, 4, 4, 2),
        ('fp16', (0, 1), 8, 4, 4, 8),
        ('fp32', (3, 1, 1), 1, 8, 16, 1),
        ('fp32', (1, 5, 6, 0, 1), 2, 4, 8, 2),
        ('fp16', (2, 6, 0, 1), 16, 8, 16, 4),
        ('fp32', (8, 11, 1, 1, 1), 1, 1, 4, 2),
        ('fp16', (4, 6, 0, 1), 4, 8, 32, 2),
        ('fp16', (0, 2, 1), 16, 8, 8, 4),
        ('fp16', (5, 3, 2, 1), 2, 16, 32, 2),
        ('fp16', (2, 3, 1), 4, 2, 8, 2),
        ('fp16', (2, 1, 2, 1), 8, 8, 16, 2)
    ]

    for dtype, subband_counts, Wmax, Dcore, Dout, Tinner in kernels:
        fs = cuda_generator.FrequencySubbands(subband_counts = subband_counts)
        yield cuda_generator.PeakFinder(dtype, fs, Wmax, Dcore, Dout, Tinner)

    
def autogenerated_cdd2_kernels():
    """
    Generates objects of type 'cuda_generator.CoalescedDdKernel2'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)

    Kernels are represented by rows

        (dtype, dd_rank, Wmax, Tinner, subband_counts, num_early_triggers)

    which is one primary tree of a DedispersionConfig: 'subband_counts' is a CONFIG's
    frequency_subband_counts, and each early-trigger level e in 0..num_early_triggers emits
    one kernel, at dd_rank-e with the counts restricted by e.

    A row can be unbuildable in several ways (see cuda_generator.check_cdd2_params(), called
    in the loop at the bottom). To add rows, use 'pirate_frb dev random_kernels --cdd2',
    which calls the same validator, so its output is buildable by construction.
    """

    kernels = [ ]

    # ---------------------------------------------------------------------------------
    #
    # Baseline kernels, so that the unit tests run with every flag below unset.
    #
    # FIXME Wmax=32 is broken in these "toy-size" kernels (it works in production-size
    # ones), which is why the ladders stop at 16.

    # THE SHAPE OF THE LADDERS IS LOAD-BEARING for DedispersionConfig::make_random(), which
    # draws its keys from this registry. Three properties, all of the registry rather than of
    # the draw, and all only about rows with dd_rank <= 5 (make_random()'s reach at the
    # default max_toplevel_rank=10, so the production rows below do not contribute):
    #
    #   1. SEVERAL Wmax PER (dtype, dd_rank, subband_counts) GROUP. validate() requires a
    #      downsampled primary tree's max_width to equal its predecessor's or be half of it,
    #      so a group stocking one Wmax can only yield a flat max_width chain -- and hence
    #      never a config whose nprofiles varies across primary trees.
    #
    #   2. THE SAME SUBBAND VECTOR AT CONSECUTIVE dd_rank. make_random() draws
    #      toplevel_tree_rank from {2*dd_rank-1, 2*dd_rank}, so a downsampled group sits one
    #      dd_rank lower. With no partner row there, half the draws fall back to a single
    #      primary tree.
    #
    #   3. AT LEAST ONE VECTOR THAT CLAMPS BELOW ITS TOP LEVEL under restriction, which is
    #      what makes an early-trigger tree's multiplet map non-contiguous -- the only case
    #      where a wrong gather in restrict_fine_vector() is visible. (2,2,1) and (2,3,1)
    #      clamp only at their new top level, so before (4,2,1) was stocked no gpu_valid draw
    #      could produce one (measured: 0 of 439 parent/child pairs), while both shipped
    #      early-trigger configs are full of them.
    #
    # Measured with 'pirate_frb dev coverage' -- RE-RUN IT AFTER CHANGING ANYTHING HERE. It
    # reports the dtypes separately, which is why the ladders stock both. Fraction of draws
    # whose max_width varies across primary trees: 31% fp32 / 29% fp16, against 12% / 18%
    # with a single Wmax and no ladder.

    for Wmax in [16, 8, 4]:
        kernels += [
            # (dtype, dd_rank, Wmax, Tinner, subband_counts, num_early_triggers)
            ('fp32', 4, Wmax, 1, (2,2,1), 1),
            ('fp32', 5, Wmax, 1, (2,2,1), 2),
            ('fp32', 6, Wmax, 2, (2,2,1), 2),   # configs/dedispersion/toy.yml
            ('fp16', 4, Wmax, 2, (2,3,1), 1),   # et 2 would give dd_rank 2, not two-stage
            ('fp16', 5, Wmax, 2, (2,3,1), 2),
            ('fp16', 6, Wmax, 2, (2,3,1), 2),
            ('fp32', 4, Wmax, 1, (4,2,1), 1),
            ('fp32', 5, Wmax, 1, (4,2,1), 2),
            ('fp16', 4, Wmax, 2, (4,2,1), 1),
            ('fp16', 5, Wmax, 2, (4,2,1), 2),
            ('fp16', 6, Wmax, 2, (4,2,1), 2),
            ('fp16', 5, Wmax, 2, (2,3,1,1), 2),
        ]

    # ---------------------------------------------------------------------------------
    #
    # Production kernels: one row per PRIMARY TREE of configs/dedispersion/*.yml, which is
    # the bare minimum those configs need. CoalescedDdKernel2::time_selected() mirrors the
    # distinct subband_counts below by hand.
    #
    # Wmax is per row, rather than the list being crossed with [32,16,8,4]. Crossing is what an
    # earlier version did, and it over-generates badly: max_width and num_early_triggers are
    # BOTH properties of a primary tree and move together down the max_width chain
    # (chime_sb2_et has (32,0), (16,1), (8,2), (4,3)), so the cross product asks for things
    # like Wmax=32 at et_level=3, which no config can use. 61 kernels crossed, 40 as written.

    if production_kernels:
        kernels += [
            ('fp16', 8, 32, 1, (0,0,0,0,1), 0),   # chime, chord_sb0
            ('fp16', 7, 16, 1, (0,0,0,0,1), 0),   # chime
            ('fp16', 8, 16, 1, (0,0,0,0,1), 0),   # chord_sb0
            ('fp16', 7,  8, 1, (0,0,0,0,1), 0),   # chime
            ('fp16', 8,  8, 1, (0,0,0,0,1), 0),   # chord_sb0
            ('fp16', 7,  4, 1, (0,0,0,0,1), 0),   # chime
            ('fp16', 8,  4, 1, (0,0,0,0,1), 0),   # chord_sb0

            ('fp16', 8, 32, 1, (0,0,1,2,1), 0),   # chime_sb1
            ('fp16', 7, 16, 1, (0,0,1,2,1), 0),   # chime_sb1
            ('fp16', 7,  8, 1, (0,0,1,2,1), 0),   # chime_sb1
            ('fp16', 7,  4, 1, (0,0,1,2,1), 0),   # chime_sb1

            ('fp16', 8, 32, 1, (0,5,7,3,1), 0),   # chime_sb2, chime_sb2_et
            ('fp16', 7, 16, 1, (0,5,7,3,1), 0),   # chime_sb2
            ('fp16', 7, 16, 1, (0,5,7,3,1), 1),   # chime_sb2_et
            ('fp16', 7,  8, 1, (0,5,7,3,1), 0),   # chime_sb2
            ('fp16', 7,  8, 1, (0,5,7,3,1), 2),   # chime_sb2_et
            ('fp16', 7,  4, 1, (0,5,7,3,1), 0),   # chime_sb2
            ('fp16', 7,  4, 1, (0,5,7,3,1), 3),   # chime_sb2_et

            ('fp16', 8, 32, 1, (1,2,2,2,1), 0),   # chord_sb1
            ('fp16', 8, 16, 1, (1,2,2,2,1), 0),   # chord_sb1
            ('fp16', 8,  8, 1, (1,2,2,2,1), 0),   # chord_sb1
            ('fp16', 8,  4, 1, (1,2,2,2,1), 0),   # chord_sb1

            ('fp16', 8, 32, 1, (5,9,7,3,1), 0),   # chord_sb2, chord_sb2_et
            ('fp16', 8, 16, 1, (5,9,7,3,1), 0),   # chord_sb2
            ('fp16', 8, 16, 1, (5,9,7,3,1), 1),   # chord_sb2_et
            ('fp16', 8,  8, 1, (5,9,7,3,1), 0),   # chord_sb2
            ('fp16', 8,  8, 1, (5,9,7,3,1), 2),   # chord_sb2_et
            ('fp16', 8,  4, 1, (5,9,7,3,1), 0),   # chord_sb2
            ('fp16', 8,  4, 1, (5,9,7,3,1), 3),   # chord_sb2_et

            # The shipped configs are all float16. These are for make_mini_chord(float32),
            # whose trees are all (dd_rank 8, max_width 16); without them the float32 half
            # of CoalescedDdKernel2::time_selected() is skipped. toy.yml is float32 too, but
            # its kernels come from the ladder rows above.

            ('fp32', 8, 16, 1, (0,0,0,0,1), 0),
            ('fp32', 8, 16, 1, (0,0,1,2,1), 0),
            ('fp32', 8, 16, 1, (0,5,7,3,1), 0),
            ('fp32', 8, 16, 1, (1,2,2,2,1), 0),
            ('fp32', 8, 16, 1, (5,9,7,3,1), 0),
        ]

    # ---------------------------------------------------------------------------------
    #
    # Debug kernels. The first list is from 'pirate_frb dev random_kernels --cdd2'.

    if debug_cdd2_kernels or debug_gpu_dd:
        # From 'pirate_frb dev random_kernels --cdd2'.

        kernels += [
            ('fp32', 3,  4, 4, [1],             0),
            ('fp32', 3, 16, 2, [4, 1, 1],       0),
            ('fp32', 7,  1, 2, [4, 11, 7, 3, 1], 3),
            ('fp32', 8,  1, 2, [4, 11, 7, 3, 1], 4),
            ('fp16', 6,  1, 4, [1],             0),
            ('fp16', 7,  1, 4, [1],             0),
            ('fp16', 4,  2, 1, [1],             0),
            ('fp16', 5,  2, 1, [1],             0),
            ('fp32', 7,  8, 2, [2, 1, 1],       2),
            ('fp32', 8,  8, 2, [2, 1, 1],       2),
            ('fp32', 5,  1, 2, [1],             0),
            ('fp32', 6,  1, 2, [1],             0),
            ('fp16', 4,  4, 8, [0, 0, 1],       0),
            ('fp16', 5,  4, 8, [0, 0, 1],       0),
            ('fp32', 3,  8, 8, [1, 1],          0),
            ('fp32', 4,  8, 8, [1, 1],          1),
            ('fp16', 6,  8, 4, [8, 0, 1, 1],    0),
            ('fp16', 7,  8, 4, [8, 0, 1, 1],    1),
            ('fp16', 6,  8, 1, [4, 3, 1],       1),
            ('fp16', 7,  8, 1, [4, 3, 1],       0),
            ('fp32', 6, 16, 2, [5, 5, 1, 1],    3),
            ('fp32', 7, 16, 2, [5, 5, 1, 1],    3),
            ('fp16', 5,  8, 4, [1],             0),
            ('fp16', 6,  8, 4, [1],             0),
            ('fp32', 6,  2, 1, [2, 1],          1),
            ('fp32', 7,  2, 1, [2, 1],          0),
            ('fp32', 4,  4, 4, [1],             0),
            ('fp32', 5,  4, 4, [1],             0),
        ]

    if debug_cdd2_kernels:
        # Five kernels chosen by hand, on top of the random ones above.
        #
        # A cdd2 kernel searches some number of frequency subbands, while the GPU kernel's
        # second dedispersion stage has 2^dd_rank1 DM slots per warp. When there are fewer
        # subbands than slots, the kernel folds the spare DM bits into its output, and the
        # code it generates to do that differs a lot from case to case -- these kernels are
        # fully unrolled, so two of them differ by thousands of lines rather than by a
        # constant. The random kernels above hit that case often, but never at its extremes.
        #
        # All but the last are at dd_rank 8, which is what CHIME and CHORD use, and where
        # shared memory is tightest (90 KB out of the 100 KB a threadblock can have).

        kernels += [
            # The two largest kernels in the build: 50 multiplets, 16 warps, 6-7k lines each.
            # If anything is going to run out of registers or shared memory, it is these.
            ('fp32', 8, 16, 1, (3,3,2,1), 0),
            ('fp16', 8,  8, 2, (3,3,2,1), 0),

            # The opposite corner: one subband against 16 DM slots. Every lag the kernel
            # applies is zero here, so a lag bug that cancels out elsewhere is visible.
            ('fp32', 8, 16, 1, (1,),      0),
            ('fp16', 8,  8, 2, (1,),      0),

            # The only odd dd_rank, so its two dedispersion stages have ranks 3 and 4 where
            # every other kernel here has equal stages. float16 because odd lags take a
            # separate half-precision alignment path.
            ('fp16', 7,  8, 2, (2,1),     0),
        ]

    # ---------------------------------------------------------------------------------
    #
    # Final loop, expanding early triggers, and converting tuples -> (CoalescedDdKernel2 objects).

    for dtype, dd_rank0, Wmax, Tinner, subband_counts, num_early_triggers in kernels:
        for et_level in range(num_early_triggers + 1):
            dd_rank = dd_rank0 - et_level
            sbc = cuda_generator.FrequencySubbands.restrict_subband_counts(subband_counts, et_level)

            # Checked here rather than left to the generator, which would raise a bare
            # AssertionError naming no kernel.
            err = cuda_generator.check_cdd2_params(dtype, dd_rank, sbc, Wmax, Tinner)
            if err is not None:
                raise RuntimeError(f"autogenerated_cdd2_kernels: unusable row ({dtype},"
                                   f" {dd_rank0}, {Wmax}, {Tinner},"
                                   f" {tuple(subband_counts)}, {num_early_triggers}): {err}")

            fs = cuda_generator.FrequencySubbands(subband_counts = sbc)
            yield cuda_generator.CoalescedDdKernel2(dtype, dd_rank, fs, Wmax, Tinner)


def autogenerated_sbdd_kernels():
    """
    Generates objects of type 'cuda_generator.SbDedisperser'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    # An sbdd kernel is the dedispersion half of a cdd2 kernel, compiled to run on its own.
    # It is much cheaper to build, and 'pirate_frb varmap bf' needs one for whatever tree its
    # config describes while never needing the matching cdd2 kernel -- so this list is
    # deliberately wider than the cdd2 one.
    #
    # A missing sbdd kernel is a hard error, not a slow path: the GpuSbDedispersionKernel
    # constructor throws "Kernel not found in registry", naming the (dd_rank, subband_counts)
    # it wanted, before the sweep starts. The escape hatch is 'varmap bf --cpu', which needs
    # no gpu kernel at all.

    # One per cdd2 kernel, so that sbdd coverage tracks cdd2 coverage and the two cannot
    # drift apart. An sbdd kernel is identified by (dd_rank, subband_counts) alone, so the
    # float16 and float32 variants of a tree, and all of its max_widths, collapse onto one.

    for cdd2 in autogenerated_cdd2_kernels():
        yield cuda_generator.SbDedisperser(cdd2.dd_rank, cdd2.frequency_subbands)

    # A sweep over tree size and subband structure, for configs written by hand rather than
    # drawn from the registry -- which is what 'varmap bf' is usually pointed at. dd_rank
    # 3..8 covers tree rank 5..16, i.e. subscale through CHIME (15) and CHORD (16).
    #
    # Two shapes per size: one band, and several. 'subband_counts' says how many bands sit
    # at each level, so leading zeros mean a tree that divides its band coarsely. There is
    # little point sampling more finely than this -- an sbdd kernel is about 1500 generated
    # lines and two of them that differ only in band count differ by well under 10% of it.

    shapes = {
        0: [ (1,) ],
        1: [ (0,1), (2,1) ],
        2: [ (0,0,1), (2,2,1) ],
        3: [ (0,0,0,1), (0,2,2,1) ],
        4: [ (0,0,0,0,1), (0,0,2,2,1) ],
    }

    for dd_rank in range(3, 9):
        for pf_rank in range((dd_rank + 1) // 2 + 1):
            for subband_counts in shapes[pf_rank]:
                fs = cuda_generator.FrequencySubbands(subband_counts = list(subband_counts))
                yield cuda_generator.SbDedisperser(dd_rank, fs)


def autogenerated_pf_weight_reader_kernels():
    """
    Generates objects of type 'cuda_generator.PfWeightReader'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    if not debug_pfwr_kernels:
        return
    
    # Add some randomly generated kernels.
    # python -m pirate_frb dev random_kernels --pfwr

    # (dtype, subband_counts, Dcore, P, Tinner)
    kernels = [
        ('fp32', (2,1,1), 1, 14, 16),
        ('fp16', (7,6,2,1), 8, 10, 2),
        ('fp32', (0,2,1), 1, 1, 4),
        ('fp16', (4,0,1,1), 2, 5, 1),
        ('fp32', (3,2,1), 1, 5, 32),
        ('fp16', (14,4,4,0,1), 8, 3, 2),
        ('fp16', (13,7,3,0,1), 4, 3, 4),
        ('fp16', (3,2,1), 2, 7, 32),
        ('fp32', (6,5,1,1,1), 4, 2, 4),
        ('fp32', (4,3,1,1), 2, 2, 8),
        ('fp32', (3,2,1), 8, 5, 4),
        ('fp16', (1,1,1), 4, 2, 1),
        ('fp32', (9,4,0,2,1), 16, 8, 1),
        ('fp32', (0,2,1), 1, 8, 2),
        ('fp32', (3,0,1), 1, 6, 1)
    ]

    for (dtype, subband_counts, Dcore, P, Tinner) in kernels:
        fs = cuda_generator.FrequencySubbands(subband_counts = subband_counts)
        yield cuda_generator.PfWeightReader(fs, dtype, Dcore, P, Tinner)


def autogenerated_pf_output_kernels():
    """
    Generates objects of type 'cuda_generator.PfOutput'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    # In this case, we can enumerate all valid parameter choices
    # (i.e. no need to randomly generate kernels).

    if not debug_pfo_kernels:
        return
    
    for (dtype,Lmin) in [ ('float',0), ('__half',1) ]:
        for L in range(Lmin, 6):
            yield cuda_generator.PfOutput(dtype, Dout=2**L)


